source('mp10_immune_endothelial_mechanisms_v1/scripts/common.R');source(file.path(S,'nichenet_native_metrics.R'));lt<-readRDS(file.path(REF,'ligand_target_matrix_nsga2r_final.rds'));m20<-scan(file.path(P,'neighborhood_mp10_calibration_v5/01_score_fidelity/top20.txt'),what='character',quiet=TRUE);out<-list()
for(spec in list(c('M0001','Full','positive'),c('M0001','Full','negative'),c('M0001','M20-masked','positive'),c('M0003','Full','union'))){id<-spec[1];mask<-spec[2];sg<-spec[3];f<-tb(paste0('nichenet/',id,'_',mask,'_',sg,'_0.1.tsv.gz'));if(!file.exists(f))next;native<-fread(f);de<-rd(paste0('de/',id,'.tsv.gz'));bg<-intersect(de$gene,rownames(lt));if(mask=='M20-masked')bg<-setdiff(bg,m20);target<-intersect(de[FDR<.05&if(sg=='positive')logFC>0 else if(sg=='negative')logFC<0 else TRUE,gene],bg)
 t<-system.time(fast<-nichenet_four_metrics(target,bg,lt,native$test_ligand));z<-merge(native,fast,by='test_ligand',suffixes=c('_native','_fast'));for(v in c('auroc','aupr','aupr_corrected','pearson')){a<-z[[paste0(v,'_native')]];b<-z[[paste0(v,'_fast')]];diff<-max(abs(a-b),na.rm=TRUE);ok<-identical(is.na(a),is.na(b))&&is.finite(diff)&&diff<1e-12;out[[length(out)+1]]<-data.table(model_id=id,mask=mask,target_direction=sg,metric=v,n_ligands=nrow(z),max_absolute_error=diff,pass=ok,elapsed_seconds=t['elapsed'])}}
z<-rbindlist(out);put(z,'nichenet_native_metrics_validation.tsv');print(z);stopifnot(nrow(z)>=12,all(z$pass));writeLines('validated: public four metrics identical within 1e-12',file.path(B,'config/nichenet_fast_metrics_validated.txt'))
